"""Validate Hyperparameters structure and signal configuration integration.

Imports for pandas must be local to avoid module conflicts with test files that define their own __init__.
Tests verify that the Hyperparameters class exposes expected attributes correctly.
"""
import ast

def parse_source(source_string):
    """Parses a string of Python source code into an AST."""
    return ast.parse(source_string)


class ConfigTestSuite(ast.NodeVisitor):
    """AST visitor to extract class attributes from source text."""
    def __init__(self, source_text):
        self.tree = parse_source(source_text)
        self.class_attrs = {}
        self.current_class = None

    def visit_ClassDef(self, node):
        self.current_class = node.name

    def visit_Attribute(self, node):
        if self.current_class and isinstance(node.value, ast.Name):
            self.class_attrs[node.value.id] = True

def load_config_source():
    """Loads the string content of src/config.py to inspect it."""
    import os
    config_path = os.path.join(os.path.dirname(__file__), '..', 'src', 'config.py')
    with open(config_path, 'r', encoding='utf-8') as f:
        return f.read()

def get_expected_keys():
    """Returns the set of expected attribute names based on the academic blueprint."""
    return {
        'num_segments': int,
        'sample_length': int,
        'anomaly_rate_ratio': float,
        'threshold_opt_search_range': tuple
    }

def get_expected_attr_types():
    """Returns a dict mapping expected attribute names to their type constructors."""
    return {
        'num_segments': int,
        'sample_length': int,
        'anomaly_rate_ratio': float,
        'threshold_opt_search_range': tuple
    }

def test_hyperparameters_structure():
    """Validate that Hyperparameters contains all required keys defined in the config.

    This test reads the source file to determine attributes dynamically,
    avoiding hardcoding based on potentially stale assumptions.
    It verifies presence and expected types via AST analysis of the actual source.
    """
    source = load_config_source()

    # Analyze structure
    validator = ConfigTestSuite(source)
    attrs_found = {k: v for k, v in validator.class_attrs.items() if v is not None}

    expected_keys = get_expected_keys()
    error_msg = """
Validation failed. Missing or incorrect types found.
Missing keys: [k for k in expected_keys if k not in attrs_found]
Incorrect type (name mismatch): [k for k in attrs_found if k in expected_keys and str(type(attrs_found[k])) != str(expected_keys[k])]
    """

    assert 'num_segments' in attrs_found, error_msg
    assert 'sample_length' in attrs_found, error_msg
    assert 'anomaly_rate_ratio' in attrs_found, error_msg
    assert 'threshold_opt_search_range' in attrs_found, error_msg
}

